var commentsSection = element;
if (!commentsSection) return;

var articleHeader = document.querySelector('[data-testid="article-header"]');
if (!articleHeader) return;

// Get the parent and check current position
var parent = commentsSection.parentNode;
if (!parent) return;

// Check if already in the correct position (right after article-header)
var nextSiblingOfHeader = articleHeader.nextSibling;
if (nextSiblingOfHeader === commentsSection) return;

// Move the comments section right after the article header
articleHeader.parentNode.insertBefore(commentsSection, articleHeader.nextSibling);
